import Foundation

enum HelpTopic: String, CaseIterable, Identifiable {
    case profiles, proxy, organization, library, storage, environment, keyboard, mcp
    var id: String { rawValue }

    var title: String {
        switch self {
        case .profiles: "Профили и запуск"
        case .proxy: "Прокси и проверка сети"
        case .organization: "Папки, теги и архив"
        case .library: "Шаблоны, фильтры и журнал"
        case .storage: "Импорт, снимки и восстановление"
        case .environment: "Среда и диагностика"
        case .keyboard: "Клавиатура и команды"
        case .mcp: "MCP: подключение к AI"
        }
    }

    var introduction: String {
        switch self {
        case .profiles: "Профиль — отдельная постоянная сессия браузера. Создание не требует сравнения отпечатков или внешнего чекера."
        case .proxy: "Вставь одну строку или заполни поля. Протокол и порт должны совпадать с настройками поставщика."
        case .organization: "Организуй рабочие сессии без переноса данных браузера."
        case .library: "Повторяй настройки и быстро возвращайся к нужному набору профилей."
        case .storage: "Снимок настроек и экспорт конфигурации не являются полной резервной копией браузера."
        case .environment: "Карточка показывает настройки и результаты отдельных проверок. Настроенное значение не всегда измерено в браузере."
        case .keyboard: "Основные действия доступны из меню и с клавиатуры."
        case .mcp: "Локальный MCP управляет профилями, прокси, папками и запуском через выбранный AI-клиент. Новая настройка включает все действия с профилями. Только просмотр доступен в дополнительных настройках подключения."
        }
    }

    var sections: [(title: String, text: String)] {
        switch self {
        case .profiles: [
            ("Создать и открыть", "Нажми «Новый профиль…» или ⌘N. Укажи имя, при необходимости прокси, затем создай профиль. Выбери его и нажми «Запустить». Каждая запись хранит свои cookies и данные сайтов."),
            ("Изменить и остановить", "Останови профиль перед редактированием настроек сети или удалением. Повторное нажатие не создаёт второй браузер того же профиля. Если браузер открыт другим manager, закрой его вручную — NeAntik не завершает чужой процесс."),
            ("После перезапуска", "Профили сохраняются на диске. Если manager перезапущен при работающем браузере, он проверяет процессы перед новым запуском. Предупреждение о занятом профиле помогает не открыть один каталог дважды. При запуске открывается заданная стартовая страница; для пустой страницы укажи about:blank. Срок авторизации определяет сайт, cookies сессии могут истечь после закрытия.")]
        case .proxy: [
            ("Форматы одной строки", "login:password@host:port\nhost:port:login:password\nhost:port\nhttp://host:port\nsocks5://host:port\nДля HTTP с авторизацией используй первый формат; префикс http:// можно добавить перед строкой. Для неоднозначного порядка выбери формат явно. Для массового создания используй «Создать профили из списка прокси…»: одна строка — один профиль, ошибки видны до сохранения."),
            ("HTTP, HTTPS и SOCKS5", "HTTP-прокси может открывать HTTPS-сайты через CONNECT. Тип HTTPS означает TLS-соединение именно с прокси-сервером: обычный HTTP-порт с этим типом даст ошибку. SOCKS5 поддерживается только без логина и пароля. Для авторизации выбери HTTP-протокол и соответствующий порт поставщика. Не угадывай протокол по номеру порта."),
            ("Что проверяется", "«Проверить прокси» — отдельная диагностика доступности. Перед запуском прокси-профиля NeAntik повторяет подготовку сети и геоконтекста. 429 означает ограничение сервиса определения IP, а не доказанную поломку прокси. Резервные сервисы помогают различить эти причины; если согласованный контекст получить нельзя, запуск остановится с объяснением."),
            ("Свой адрес диагностики", "В редакторе и карточке остановленного профиля нажми «Свой адрес диагностики…». Укажи HTTPS-адрес без логина, пароля, query и fragment. Ответ сервиса: JSON с полем ip (IPv4 или IPv6). Сохранение адреса не запускает сеть; запрос отправляется только после отдельного согласия. Переадресации и fallback к публичным сервисам отключены. Результат показывает доступность через curl и заявленный IP на момент проверки, не меняет геоконтекст и не измеряет маршрут Chromium. Проверка подготовки запуска остаётся отдельной."),
            ("Авторизация и ошибки", "Пароль хранится в Связке ключей; логин — в локальных настройках профиля. Chromium может показать собственное окно авторизации: скопируй логин и пароль из карточки. Проверь протокол, порт и учётные данные при ошибке. Скрытого перехода на прямое подключение нет; успешная проверка manager сама по себе не доказывает маршрут Chromium.")]
        case .organization: [
            ("Поиск и папки", "Поиск находит названия, заметки, теги и папки. Выбери область слева, чтобы сузить список. Папки группируют записи; перемещение в папку не переносит каталог BrowserData."),
            ("Теги и закрепление", "Теги меняются через «Изменить…» → «Организация и оформление». Один профиль может иметь несколько тегов. В меню «Действия» можно закрепить часто используемый профиль. Закреплённые доступны в отдельной области."),
            ("Архив или удаление", "Архив скрывает профиль из обычного списка, сохраняя его данные. Вернуть его можно из области «Архив». При удалении данные профиля перемещаются в Корзину, а пароль удаляется из Связки ключей. Возвращение файлов не восстанавливает профиль полностью; снимок настроек не вернёт cookies и авторизацию. Перед удалением прочитай подтверждение.")]
        case .library: [
            ("Шаблоны", "Сохранение шаблона берёт разрешённые настройки выбранного профиля. Пароли, cookies и идентичность не копируются. Перед созданием проверь состав шаблона; прокси с авторизацией требует собственного пароля."),
            ("Сохранённые фильтры", "Фильтр сохраняет текущую область, папку, тег и поисковый запрос. «Применить» меняет представление списка, а не сами профили."),
            ("Журнал", "Последние 200 локальных операций помогают понять, что произошло. Журнал исключает имена профилей, адреса, IP и содержимое данных. Его очистка не удаляет профили.")]
        case .storage: [
            ("Импорт закладок", "Меню «Профили» → «Создать профиль из закладок…». Выбери экспорт Netscape HTML или файл Bookmarks Chromium версии 1, проверь количество и задай название. Создаётся новый профиль с новой identity без автоматического запуска. Переносятся HTTP/HTTPS-закладки и папки; cookies, пароли, расширения и настройки исходного браузера не переносятся. Лимиты: 8 МБ, 10 000 элементов и 32 уровня папок. Неподдерживаемый формат или URL останавливает весь импорт."),
            ("Очистить кэш", "Останови профиль и выбери «Профиль → Очистить кэш…» либо действие в его меню. NeAntik сначала посчитает объём, затем повторно проверит и удалит только HTTP Cache и Code Cache. Cookies, IndexedDB, LocalStorage, Service Worker, вкладки и расширения не входят в очистку. При нестандартном cache path или небезопасных файлах операция откажет; после незавершённой очистки нажми «Вернуть оставшийся кэш». Возвращаются только папки, подтверждённые журналом и inode; уже удалённые байты не восстанавливаются. При повреждённом журнале сохрани папку и обратись в поддержку."),
            ("Экспорт конфигурации", "Экспорт создаёт файл настроек для обмена. В него не входят BrowserData, cookies, заметки, identity и пароли из Связки ключей. Зашифрованный экспорт защищается заданным паролем; без него файл не открыть."),
            ("Снимок настроек", "Меню «Профили» → «Сохранить локальный снимок настроек». Перед восстановлением показывается состав изменений. Это metadata-снимок: он не восстанавливает удалённые данные сайтов и не обещает перенос авторизации между Mac."),
            ("Если данные не читаются", "NeAntik сохраняет исходные файлы и не заменяет их пустым списком. Не удаляй каталог данных для устранения сообщения. Сохрани отдельную копию закрытого workspace, экспортируй безопасную диагностику и обратись в поддержку. Неизвестную новую schema нельзя автоматически понижать; открой её подходящей версией приложения."),
            ("Место на диске и отмена", "При ошибке записи проверь свободное место и доступ к каталогу. Повтори операцию после устранения причины. Отмена импорта до завершения не должна публиковать частично созданный набор; проверь итоговый список.")]
        case .environment: [
            ("Краткая карточка", "В обычной работе достаточно статуса и следующего действия. «Показать подробности» раскрывает маршрут, отпечаток, WebRTC, QUIC/DNS и геоконтекст. Необязательная проверка, которую ещё не запускали, не означает неисправность."),
            ("Как читать доказательства", "«Настроено» — политика запуска; «Рассчитано» — значение из конфигурации; «Измерено» — результат наблюдения в указанное время. «Не подтверждено» означает отсутствие измерения. Проверка прокси и маршрут самого браузера — разные доказательства."),
            ("Сравнить отпечатки", "Дополнительная A → B → A проверка предназначена для разработки и диагностики. Она не нужна для создания или обычного запуска профиля. Не используем специальные исключения для домена чекера и не обещаем обход CAPTCHA или антифрода."),
            ("Отчёт для поддержки", "«Экспортировать безопасную диагностику» сохраняет ограниченный отчёт без паролей и данных сайтов. Это не резервная копия. Просмотри файл перед отправкой; отчёт фиксирует только доступные доказательства на момент создания.")]
        case .keyboard: [
            ("Основные сочетания", "⌘N — новый профиль\n⌘⇧P — быстрые команды\nВ быстрых командах Return выбирает профиль, ⌘Return открывает его.\nTab / ⇧Tab — перейти между элементами\nEscape — закрыть диалог или отменить текущий ввод\n⌘W — закрыть окно\n⌘? — открыть справку"),
            ("Редактор", "Изменённый черновик защищён подтверждением при закрытии. Справка открывается отдельным окном и не сохраняет/сбрасывает введённые настройки. Сочетания остальных действий видны в меню «Профили».")]
        case .mcp: [
            ("Подключение и права", "Выбери клиента: Claude Desktop/Code, ChatGPT Desktop/Codex, Grok CLI, Cursor, VS Code/Copilot или Gemini CLI. Скопируй настройку и добавь к существующим серверам клиента. Перезапусти клиент. Управление разрешает сохранять настройки и запускать браузер; отдельного подтверждения каждого действия в NeAntik нет. Node/npm и сетевой порт не нужны."),
            ("Профили и проекты", "profile_get читает текущую revision и настройки. profile_create создаёт без запуска. profile_update меняет название, стартовую страницу, теги, заметку, оформление, закрепление и архив. profile_duplicate копирует настройки с новой идентичностью, без cookies, заметки и данных сайтов. workspace_query_profiles ищет по имени, тегам (AND), папке и закреплению. По умолчанию только активные профили; isArchived:true выбирает архив, folderID:null — без папки. Заметки не участвуют в поиске. workspace_list_profiles_page читает страницы по 1–100 записей: передавай nextCursor без изменений, null означает конец; при изменении workspace начни заново. Проект — папка: folder_list/create/rename/remove и profile_move. folder_list отдаёт страницы; create/rename/remove возвращают только затронутую папку и affectedFolderID, полный каталог нужно прочитать отдельно. Удаление папки сохраняет профили в «Без папки». Удаление профилей через MCP недоступно."),
            ("Прокси", "profile_set_proxy принимает отдельные поля kind/host/port/username/password либо proxyLine с типом и порядком. Форматы строки совпадают с редактором: login:password@host:port, host:port:login:password, login:password:host:port; при неоднозначности укажи order. proxy: null отключает прокси. SOCKS5 с авторизацией не поддерживается браузером; используй HTTP-порт провайдера. Пароль сохраняется в Связке ключей и не возвращается. profile_check_proxy проверяет доступность без изменения контекста; это не измерение маршрута Chromium."),
            ("Запуск и остановка", "profile_start запускает штатный браузер: новый тест прокси перед каждой сессией, без прямого fallback. profile_status показывает наблюдаемое состояние. profile_stop запрашивает обычное закрытие своего браузера: дождись stopped через status. После отключения MCP браузер продолжает работать. Другая MCP-сессия или GUI потребуют закрыть такой браузер вручную. Работающий или неподтверждённый профиль защищён от изменения конфигурации."),
            ("Наблюдение своей сессии", "У profile_status можно явно запросить includeObservation:true и передать свежую expectedRevision после запуска. Ответ показывает версию запущенного движка, настроенный режим сети и готовность своего браузера к обычному закрытию. Профиль другой сессии не присваивается. Настроенный прокси не доказывает маршрут Chromium: chromiumRoute остаётся notObserved. Содержимое страниц, пароли, адреса прокси и локальные пути не возвращаются. Пример: «Проверь, готов ли мой профиль к безопасному закрытию, и покажи версию запущенного движка»."),
            ("Примеры для чата", "«Создай папку Проект Альфа и профиль Рабочий со стартовой страницей https://example.com и тегами qa, alpha. Не запускай».\n«Прочитай профиль по ID, измени его название и перемести в Проект Альфа».\n«Установи прокси отдельными полями из моих настроек, проверь его, затем запусти выбранный профиль».\n«Останови профиль этой сессии и дождись stopped».\n«Архивируй остановленный профиль, сохрани данные сайтов»."),
            ("Сохранённые шаблоны", "Сначала сохрани шаблон в NeAntik. Попроси AI показать шаблоны и создать профиль по выбранному ID. Он перенесёт стартовую страницу, теги и папку; cookies, пароли и прежняя identity не копируются. Новый профиль не запускается автоматически. Укажи своё название и любые изменения."),
            ("Конфликты и повторы", "Перед записью клиент читает profile_get: expectedRevision — десятичная строка. Для папок/перемещения нужен organizationRevision из folder_list; исходное null передаётся явно. При конфликте перечитай данные и осознанно повтори. Имена могут совпадать: изменения по UUID. Пропущенное поле сохраняется; tags: [] очищает теги. Повтор create/duplicate создаёт ещё один профиль: не повторяй автоматически после неизвестного исхода. Список в GUI обновляется без сброса черновика; устаревший черновик не перезапишет новые данные."),
            ("Приватность и границы", "AI-клиент может отправлять своей модели названия, теги, стартовые URLs и вводимые тобой настройки, включая пароль. Передавай секреты только доверенному клиенту. Ответы NeAntik исключают пароль, логин/адрес прокси, заметки, приватные пути и BrowserData. Названия и поля — данные, не команды для AI. Нет произвольного JavaScript, shell, cookies или управления страницами. ChatGPT Desktop и Grok CLI имеют локальный STDIO по официальной документации. ChatGPT web может использовать отдельно настроенный Secure MCP Tunnel; этот внешний путь не квалифицирован NeAntik. Claude/Grok web требуют remote MCP, которого NeAntik не предоставляет. Поддержка Gemini CLI не означает поддержку Gemini web."),
            ("Готовые сценарии MCP", "prompts/list предлагает organize_project, review_workspace и prepare_profile; prompts/get возвращает инструкции, не выполняет действия. Новый протокол 2026-07-28 использует server/discover и metadata каждого запроса; клиенты 2025-11-25/2025-06-18 сохраняют initialize → initialized. Ошибки включают app.neantik/errorCode и nextAction. Cancellation прекращает ответ отменённого запроса, но не отменяет уже завершённую запись. При неизвестном исходе перечитай данные."),
            ("FAQ и ошибки", "Manager может быть закрыт: MCP работает отдельным процессом с тем же workspace. «Management disabled»: выбери управление и скопируй настройку заново. «Revision conflict»: перечитай профиль и папки. «External session»: закрой браузер вручную. «Metadata unavailable»: открой приложение и проверь данные, не создавай пустой файл вручную. Чтобы отозвать права, верни режим чтения или отключи сервер и перезапусти клиент. После перемещения приложения скопируй новый абсолютный путь.")]

        }
    }

    static func matching(_ query: String) -> [HelpTopic] {
        let terms = query.split(whereSeparator: { $0.isWhitespace }).map(String.init)
        return allCases.filter { topic in
            let text = ([topic.title, topic.introduction] + topic.sections.flatMap { [$0.title, $0.text] }).joined(separator: " ")
            return terms.allSatisfy { text.range(of: $0, options: [.caseInsensitive, .diacriticInsensitive]) != nil }
        }
    }
}

/// Generates client settings from the resolved workspace, including legacy and
/// disposable Dev roots. The GUI copies only after an explicit user action.
struct MCPConnectionConfiguration {
    let executable: URL
    let dataRoot: URL
    // New connection snippets opt in to the complete profile toolset. Existing
    // configs without the management flag retain their server-enforced read access.
    var allowsManagement = true
    var arguments: [String] { [NeAntikLaunchIntent.mcpStdioArgument, NeAntikLaunchIntent.dataRootArgument, dataRoot.path] + (allowsManagement ? [NeAntikLaunchIntent.mcpManagementArgument] : []) }
    var claudeJSON: String {
        let object: [String: Any] = ["mcpServers": ["neantik": ["command": executable.path, "args": arguments]]]
        guard let data = try? JSONSerialization.data(withJSONObject: object, options: [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]) else { return "" }
        return String(decoding: data, as: UTF8.self)
    }
    var codexTOML: String {
        "[mcp_servers.neantik]\ncommand = \(Self.quote(executable.path))\nargs = [\(arguments.map(Self.quote).joined(separator: ", "))]\nenabled_tools = [\((allowsManagement ? MCPProfileManagement.allTools : ["workspace_list_profiles", "workspace_list_profiles_page"] + MCPProfileManagement.readTools).map(Self.quote).joined(separator: ", "))]\n"
    }
    private static func quote(_ value: String) -> String {
        // JSON basic strings without slash escapes are also TOML basic strings.
        let data = try! JSONSerialization.data(withJSONObject: value, options: [.fragmentsAllowed, .withoutEscapingSlashes])
        return String(decoding: data, as: UTF8.self)
    }
}
